// Build-time classic sermon data (generated by scripts/generate-sermons.mjs).
import sermonsJson from "./sermons.json";
import manifestJson from "./manifest.json";
import type { PreacherId } from "./preachers";
export { PREACHERS, type PreacherId } from "./preachers";

/** One paragraph, an indented quotation (hymn verses, letters), or a section heading. */
export type SermonBlock = { p: string } | { q: string[] } | { h: string };
export type Sermon = {
  slug: string;
  preacher: PreacherId;
  /** Number in the original series, e.g. "1" or "39–40" (Wesley: the 1771 sermon number). */
  number: string;
  title: string;
  volume: number;
  series: string;
  /** Year the volume was published. */
  published: number;
  /** Preaching date (YYYY-MM-DD) as printed in the original (Wesley's dates before 1752 are Old Style). */
  date?: string;
  service?: string;
  /** Wesley: the note printed with the sermon on where and when it was preached. */
  occasion?: string;
  /** Editorial note shown on the sermon page (e.g. who preached it, where its title comes from). */
  note?: string;
  /** Version of the text when the preacher quotes one other than the KJV. */
  textVersion?: string;
  /** Text references as verse codes: [from] or [from, to]; verse 0 = whole chapter. Empty for multi-text sermons. */
  refs: ([number] | [number, number])[];
  quote: string;
  words: number;
  scan: { id: string; title: string; date: string; library: string | null; coverage: number };
};


export const sermons = sermonsJson as Sermon[];
export const sermonManifest = manifestJson;
/** Sermons by one preacher, in their original order. */
export const sermonsBy = (id: PreacherId) => sermons.filter(s => s.preacher === id);
export const sermonBySlug = new Map(sermons.map(s => [s.slug, s]));

const bodies = import.meta.glob<SermonBlock[]>("./bodies/*.json", { import: "default" });
export async function loadSermonBody(slug: string): Promise<SermonBlock[]> {
  const load = bodies[`./bodies/${slug}.json`];
  if (!load) throw new Error(`No text for sermon ${slug}`);
  return load();
}

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
/** "January 7, 1855" from "1855-01-07". */
export function dateLabel(iso: string) {
  const [y, m, d] = iso.split("-").map(Number);
  return `${MONTHS[m - 1]} ${d}, ${y}`;
}
